module.jsdoc:
@module app:lowcode/resources/semi-structured/excel-import/metadata/queries
职责：通过原DataSet的独立查询视图读取转换校验所需正式元数据。
边界：不保存、不更改浏览视图，不读取来源业务行；每次完整回读后释放临时视图。

typeAlias.declarationTypeText:
Readonly<{
    /** 原宿主已装配的数据空间。 */
    dataSet: DataSet;
    /** 正式模型名称。 */
    table: string;
    /** 复用已声明的命名视图，默认default。 */
    viewId?: string;
    /** 本次必要且必须可读的字段。 */
    fields: readonly string[];
    /** 覆盖临时视图筛选，不继承用户正在浏览的对象。 */
    filter: DataViewFilterTree;
    /** 每次异步前后验证原实例。 */
    check(): void;
}>

